<?php
namespace Azuriom\Plugin\GamingHubCore\Controllers\Admin; use Azuriom\Http\Controllers\Controller; use Azuriom\Plugin\GamingHubCore\Http\Requests\SavePublicDataSettingsRequest; use Azuriom\Plugin\GamingHubCore\Services\NormalizedDataKeys; use Azuriom\Plugin\GamingHubCore\Settings\PublicDataSettings; use Illuminate\Http\RedirectResponse; use Illuminate\View\View;
final class PublicDataSettingsController extends Controller { public function __construct(private PublicDataSettings $settings){} public function edit():View{return view('gaming-hub-core::admin.settings.public-data',['keys'=>NormalizedDataKeys::GENERIC,'policies'=>$this->settings->all()]);} public function update(SavePublicDataSettingsRequest $r):RedirectResponse{$this->settings->save($r->validated());return back()->with('success',trans('gaming-hub-core::admin.settings.saved'));} }
